1	# Result-cache experiment (E3) session helpers (docs/result-cache-experiment.md, sections 5 and 7).
2	# Written by Claude Code (Opus 5.5) on 2026-10-26 for the author's session.
3	# Load once in a Terminal window:   source <repository>/docs/result-cache-session.zsh
4	# Loading only defines the functions below, sets the variables and changes into the repository;
5	# nothing runs until a function is called. Type  e3_steps  for the checklist.
6	#
7	# Variables, read when the file is loaded (set them before loading to change them):
8	#   E3_PURPOSE   formal, dry-run, sizing or functional (default dry-run); only formal batches answer E3;
9	#                functional checks the tooling alone
10	#   E3_SEED      the workload's seed (default 1); Part A names the formal seed
11	#   E3_BATCH     the batch folder's name (default: the UTC time at loading)
12	#   E3_SWAP_OUT_MIB, E3_SWAP_IN_MIB, E3_DRIFT   the collector's limits (Part A, section 6)
13	
14	REPO=${${(%):-%x}:A:h:h}
15	cd $REPO || return 1
16	E3_PURPOSE=${E3_PURPOSE:-dry-run}
17	E3_SEED=${E3_SEED:-1}
18	E3_BATCH=${E3_BATCH:-$(date -u +%Y%m%dT%H%M%SZ)}
19	E3_SWAP_OUT_MIB=${E3_SWAP_OUT_MIB:-64}
20	E3_SWAP_IN_MIB=${E3_SWAP_IN_MIB:-256}
21	E3_DRIFT=${E3_DRIFT:-0.20}
22	E3_DIR=data/outputs-result-cache/$E3_PURPOSE/$E3_BATCH
23	E3_COMPOSE=(docker compose -f docker/compose.yaml)
24	E3_UV=(uv run --group cache --group jobs)
25	
26	e3_steps() {
27	  cat <<EOF
28	E3 session ($E3_PURPOSE), batch: $E3_DIR
29	  0. Quit other applications (the editor included); AC power, lid open; nothing else in Docker.
30	  1. e3_redis        start the redis service alone and wait for PING
31	  2. e3_preflight    exits 1 with the reasons unless a batch may start
32	  3. e3_plan         write the plan (seed $E3_SEED)
33	  4. e3_run          run it, the Mac kept awake (caffeinate -i); no other work until it ends
34	  5. e3_collect      check validity and summarize; exits 1 unless valid
35	     (e3_run and e3_collect append everything they print to \$E3_DIR/session.log)
36	  6. e3_cleanup      stop and remove the redis service only
37	EOF
38	}
39	
40	e3_redis() {
41	  $E3_COMPOSE up -d --wait redis && $E3_UV python -m etf_risk.services ready redis
42	}
43	
...
42	  if [[ $E3_PURPOSE == formal ]]; then
43	    $E3_UV python -m etf_risk.cache_experiment preflight --formal
44	  else
45	    $E3_UV python -m etf_risk.cache_experiment preflight
46	  fi
47	}
48	
49	e3_plan() {
50	  [[ $E3_PURPOSE == (formal|dry-run|sizing|functional) ]] || { echo "E3_PURPOSE must be formal, dry-run, sizing or functional"; return 2 }
51	  $E3_UV python -m etf_risk.cache_experiment plan --seed $E3_SEED --out $E3_DIR
52	}
53	
54	e3_run() {
55	  [[ -f $E3_DIR/plan.json ]] || { echo "no plan in $E3_DIR: e3_plan first"; return 2 }
56	  { e3_preflight && if [[ $E3_PURPOSE == formal ]]; then
57	      caffeinate -i $E3_UV python -m etf_risk.cache_experiment run $E3_DIR --formal
58	    else
59	      caffeinate -i $E3_UV python -m etf_risk.cache_experiment run $E3_DIR
60	    fi } 2>&1 | tee -a $E3_DIR/session.log
61	  return ${pipestatus[1]}
62	}
63	
64	e3_collect() {
65	  $E3_UV python analysis/collect_result_cache_measurements.py $E3_DIR \
66	    --swap-out-limit-mib $E3_SWAP_OUT_MIB --swap-in-limit-mib $E3_SWAP_IN_MIB --drift-limit $E3_DRIFT \
67	    2>&1 | tee -a $E3_DIR/session.log
68	  return ${pipestatus[1]}
69	}
70	
71	e3_cleanup() {
72	  $E3_COMPOSE rm --stop --force redis
73	}
